Page.content:
(() => {
  const isCategoriesPage = document.querySelector('.page.type-categories');
  if (!isCategoriesPage) return;

  const ensureChartJs = () => {
    if (typeof window.Chart !== 'undefined') return Promise.resolve();
    return new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = '/vendor/chart.js/chart.umd.min.js';
      script.onload = resolve;
      script.onerror = reject;
      document.head.appendChild(script);
    });
  };

  const pick = (arr, i) => arr[i % arr.length];

  const palette = [
    '#38bdf8', // sky
    '#818cf8', // indigo
    '#f472b6', // pink
    '#34d399', // emerald
    '#fb7185', // rose
    '#a78bfa', // violet
    '#22c55e', // green
    '#f59e0b', // amber
    '#06b6d4', // cyan
    '#e879f9'  // fuchsia
  ];

  const el = {
    root: () => document.querySelector('#page'),
    listsWrap: () => document.querySelector('#page .category-lists') || document.querySelector('#page'),
    list: () => document.querySelector('#page .category-lists > ul.category-list, #page > ul.category-list, #page .category-lists ul.category-list, #page ul.category-list')
  };

  const text = n => (n ? n.textContent : '').trim();
  const href = n => (n && n.getAttribute ? (n.getAttribute('href') || '') : '');
  const toInt = v => {
    const n = Number(String(v).replace(/[()]/g, '').trim());
    return Number.isFinite(n) ? n : 0;
  };

  function parseCategoryTree(ul, prefix = []) {
    if (!ul) return [];
    const items = [];
    const liList = [...ul.children].filter(n => n && n.tagName === 'LI');
    for (const li of liList) {
      const link = li.querySelector(':scope > a.category-list-link') || li.querySelector(':scope > a');
      const countEl = li.querySelector(':scope > .category-list-count');
      const childUl = li.querySelector(':scope > ul');
      const name = text(link) || text(li.querySelector(':scope > span'));
      const count = toInt(text(countEl));
      const url = href(link);
      const path = [...prefix, name].filter(Boolean);
      items.push({ name, path, count, depth: prefix.length, url });
      if (childUl) items.push(...parseCategoryTree(childUl, path));
    }
    return items;
  }

  function buildDashboard(treeItems) {
    const page = el.root();
    if (!page) return null;

    // If already built (pjax/themeChange), do nothing
    if (page.querySelector('.acg-catdash')) return page.querySelector('.acg-catdash');

    const dash = document.createElement('section');
    dash.className = 'acg-catdash';

    const header = document.createElement('div');
    header.className = 'acg-catdash__header';

    const title = document.createElement('div');
    title.className = 'acg-catdash__title';
    title.textContent = '文章分类统计';

    const subtitle = document.createElement('div');
    subtitle.className = 'acg-catdash__subtitle';
    subtitle.textContent = '按分类汇总文章数量（支持多级分类）';

    header.appendChild(title);
    header.appendChild(subtitle);

    const chips = document.createElement('div');
    chips.className = 'acg-catdash__chips';

    // Chips: prefer top-level categories (cleaner + more "premium")
    const top = treeItems.filter(it => it.depth === 0);
    const listForChips = (top.length ? top : treeItems).filter(it => it.count > 0);
    const sorted = [...listForChips].sort((a, b) => b.count - a.count);
    const maxChips = 12;
    const slice = sorted.slice(0, maxChips);

    slice.forEach((it, idx) => {
      const chip = document.createElement('a');
      chip.className = `acg-chip acg-chip--d${Math.min(it.depth, 2)}`;
      chip.href = it.url || '#';
      chip.title = it.path.join(' / ');

      const dot = document.createElement('span');
      dot.className = 'acg-chip__dot';
      const color = pick(palette, idx);
      chip.style.setProperty('--chip-color', color);
      dot.style.background = `radial-gradient(circle at 30% 30%, rgba(255,255,255,0.9), rgba(255,255,255,0) 58%), ${color}`;

      const label = document.createElement('span');
      label.className = 'acg-chip__label';
      label.textContent = it.depth ? it.name : it.name;

      const count = document.createElement('span');
      count.className = 'acg-chip__count';
      count.textContent = String(it.count);

      chip.appendChild(dot);
      chip.appendChild(label);
      chip.appendChild(count);

      // Hover: highlight chart slice if index matches
      chip.addEventListener('mouseenter', () => {
        const i = Number(chip.dataset.idx);
        if (!Number.isFinite(i)) return;
        const chart = dash.__chart;
        if (!chart) return;
        chart.setActiveElements([{ datasetIndex: 0, index: i }]);
        chart.update();
      });

      chip.dataset.idx = String(idx);
      chips.appendChild(chip);
    });

    const body = document.createElement('div');
    body.className = 'acg-catdash__body';

    const chartWrap = document.createElement('div');
    chartWrap.className = 'acg-catdash__chart';

    const canvas = document.createElement('canvas');
    canvas.className = 'acg-catdash__canvas';
    canvas.width = 720;
    canvas.height = 420;

    chartWrap.appendChild(canvas);
    body.appendChild(chartWrap);

    dash.appendChild(header);
    dash.appendChild(chips);
    dash.appendChild(body);

    // Insert before category list, and hide original list (keep for SEO/accessibility)
    const wrap = el.listsWrap();
    if (wrap) {
      wrap.prepend(dash);
      const list = el.list();
      if (list) {
        list.classList.add('acg-catdash__sr-list');
      }
    } else {
      page.prepend(dash);
    }

    dash.__canvas = canvas;
    return dash;
  }

  async function renderChart(dash, items) {
    if (!dash || !dash.__canvas) return;
    await ensureChartJs();
    if (typeof window.Chart === 'undefined') return;

    // Prefer top-level categories for chart clarity
    const top = items.filter(it => it.depth === 0);
    const chartItems = (top.length ? top : items).filter(it => it.count > 0);

    const labels = chartItems.map(it => it.name);
    const values = chartItems.map(it => it.count);
    const colors = chartItems.map((_, i) => pick(palette, i));

    const ctx = dash.__canvas.getContext('2d');
    if (!ctx) return;

    // Destroy existing
    if (dash.__chart) {
      try { dash.__chart.destroy(); } catch (_) {}
      dash.__chart = null;
    }

    const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
    const fontColor = isDark ? 'rgba(241,245,249,0.9)' : 'rgba(15,23,42,0.82)';
    const gridColor = isDark ? 'rgba(148,163,184,0.16)' : 'rgba(148,163,184,0.22)';
    const total = values.reduce((a, b) => a + b, 0);

    const centerTextPlugin = {
      id: 'acgCenterText',
      afterDraw(chart) {
        const { ctx } = chart;
        const meta = chart.getDatasetMeta(0);
        if (!meta || !meta.data || !meta.data.length) return;
        const x = meta.data[0].x;
        const y = meta.data[0].y;

        ctx.save();
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        ctx.fillStyle = fontColor;
        ctx.font = '800 26px Inter, system-ui, -apple-system, "Segoe UI", sans-serif';
        ctx.fillText(String(total), x, y - 6);

        ctx.fillStyle = isDark ? 'rgba(148,163,184,0.85)' : 'rgba(51,65,85,0.68)';
        ctx.font = '600 12px Inter, system-ui, -apple-system, "Segoe UI", sans-serif';
        ctx.fillText('总文章数', x, y + 18);

        ctx.restore();
      }
    };

    dash.__chart = new window.Chart(ctx, {
      type: 'doughnut',
      data: {
        labels,
        datasets: [
          {
            data: values,
            backgroundColor: colors,
            borderColor: isDark ? 'rgba(15, 23, 42, 0.55)' : 'rgba(255,255,255,0.85)',
            borderWidth: 3,
            hoverOffset: 10
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        cutout: '62%',
        plugins: {
          legend: { display: false },
          tooltip: {
            backgroundColor: isDark ? 'rgba(15,23,42,0.88)' : 'rgba(255,255,255,0.92)',
            titleColor: fontColor,
            bodyColor: fontColor,
            borderColor: gridColor,
            borderWidth: 1,
            padding: 12,
            displayColors: true,
            callbacks: {
              label: ctx => `${ctx.label}: ${ctx.parsed}`
            }
          }
        }
      },
      plugins: [centerTextPlugin]
    });
  }

  async function init() {
    const ul = el.list();
    if (!ul) return;
    const items = parseCategoryTree(ul);
    if (!items.length) return;

    const dash = buildDashboard(items);
    if (!dash) return;

    await renderChart(dash, items);
  }

  // Run now and on theme events
  init();
  if (window.btf && typeof window.btf.addGlobalFn === 'function') {
    window.btf.addGlobalFn('pjaxComplete', init, 'acg_catdash');
    window.btf.addGlobalFn('themeChange', init, 'acg_catdash_theme');
  }
})();

Page._content:
(() => {
  const KEY = 'acg_font_preset';
  const WAIFU_KEY = 'acg_hide_waifu';

  const PRESETS = [
    {
      id: 'sans',
      name: '清爽黑体',
      body: '"Inter", "Noto Sans SC", -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif',
      heading: '"Poppins", "Inter", "Noto Sans SC", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif',
    },
    {
      id: 'wenkai',
      name: '文楷',
      body: '"LXGW WenKai Screen", "Noto Sans SC", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif',
      heading: '"Poppins", "Inter", "Noto Sans SC", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif',
    },
    {
      id: 'serif',
      name: '衬线宋体',
      body: '"Noto Serif SC", "Songti SC", "STSong", "SimSun", serif',
      heading: '"Noto Serif SC", "Songti SC", "STSong", "SimSun", serif',
    },
    {
      id: 'cute',
      name: '可爱手写',
      body: '"ZCOOL KuaiLe", "LXGW WenKai Screen", "Noto Sans SC", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif',
      heading: '"ZCOOL KuaiLe", "Poppins", "Inter", "Noto Sans SC", system-ui, sans-serif',
    },
  ];

  const read = () => {
    try { return localStorage.getItem(KEY) || ''; } catch (_) { return ''; }
  };
  const write = (id) => {
    try { localStorage.setItem(KEY, id); } catch (_) {}
  };

  const readWaifu = () => {
    try { return localStorage.getItem(WAIFU_KEY) === '1'; } catch (_) { return false; }
  };
  const writeWaifu = (hidden) => {
    try { localStorage.setItem(WAIFU_KEY, hidden ? '1' : '0'); } catch (_) {}
  };

  const getPreset = (id) => PRESETS.find(p => p.id === id) || PRESETS[0];

  const applyPreset = (preset) => {
    const root = document.documentElement;
    root.dataset.font = preset.id;
    root.style.setProperty('--site-font-body', preset.body);
    root.style.setProperty('--site-font-heading', preset.heading);

    // Also set body font directly as a fallback (theme may not use the variable)
    if (document.body) {
      document.body.style.fontFamily = preset.body;
    }

    // Inject a <style> element with !important to override theme-compiled CSS
    const head = document.head || document.getElementsByTagName('head')[0];
    if (!head) return;
    let style = document.getElementById('acg-font-override');
    if (!style) {
      style = document.createElement('style');
      style.id = 'acg-font-override';
      head.appendChild(style);
    }
    // Override body & text elements, but EXCLUDE icon fonts (FontAwesome, etc.)
    var bodyFont = preset.body;
    var headFont = preset.heading;
    var monoFont = 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Courier New", monospace';
    var css = '';
    css += 'body { font-family: ' + bodyFont + ' !important; }\n';
    css += '*:not(i):not(.fas):not(.far):not(.fab):not([class*="fa-"]):not(pre):not(code):not(kbd):not(samp):not(.highlight):not(.acg-font-panel__preview) { font-family: ' + bodyFont + ' !important; }\n';
    css += 'h1, h2, h3, h4, h5, h6, .post-title, .article-title, .page-title, .page-description { font-family: ' + headFont + ' !important; }\n';
    css += 'pre, code, kbd, samp, .highlight, .code-snippet__fix, .highlight code, .highlight table, .table-wrap, .post-content code, .post-content pre { font-family: ' + monoFont + ' !important; }\n';
    style.textContent = css;
  };

  const ensureBtn = () => {
    const host = document.getElementById('rightside-config-show');
    if (!host) return null;
    let btn = document.getElementById('acg-font-switch');
    if (!btn) {
      btn = document.createElement('button');
      btn.id = 'acg-font-switch';
      btn.type = 'button';
      btn.className = 'acg-font-switch';
      btn.innerHTML = '<span class="acg-font-switch__a">A</span>';
      host.insertBefore(btn, host.firstChild);
    }
    return btn;
  };

  const updateBtn = (btn, preset) => {
    if (!btn) return;
    btn.setAttribute('title', `字体设置（当前：${preset.name}）`);
    btn.setAttribute('aria-label', `Font settings: ${preset.name}`);
    btn.dataset.preset = preset.id;
  };

  const ensurePanel = () => {
    let overlay = document.getElementById('acg-font-panel');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.id = 'acg-font-panel';
      overlay.className = 'acg-font-panel';
      overlay.innerHTML = `
        <div class="acg-font-panel__mask" data-close></div>
        <div class="acg-font-panel__card" role="dialog" aria-modal="true" aria-label="Font settings">
          <div class="acg-font-panel__header">
            <div class="acg-font-panel__title">外观设置</div>
            <button class="acg-font-panel__close" type="button" data-close aria-label="Close"><i class="fas fa-times"></i></button>
          </div>
          <div class="acg-font-panel__section">
            <div class="acg-font-panel__section-title">字体</div>
            <div class="acg-font-panel__grid" data-font-grid></div>
          </div>
          <div class="acg-font-panel__section">
            <div class="acg-font-panel__row">
              <div>
                <div class="acg-font-panel__section-title" style="margin:0">看板娘</div>
                <div class="acg-font-panel__hint">隐藏后将不遮挡页面</div>
              </div>
              <label class="acg-switch">
                <input type="checkbox" data-waifu-toggle />
                <span class="acg-switch__track"></span>
              </label>
            </div>
          </div>
        </div>
      `;
      document.body.appendChild(overlay);

      overlay.addEventListener('click', (e) => {
        const closeEl = e.target.closest('[data-close]');
        if (closeEl) {
          closePanel();
        }
      });
      window.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') closePanel();
      });
    }
    return overlay;
  };

  const openPanel = () => {
    const overlay = ensurePanel();
    overlay.classList.add('is-open');
    document.documentElement.classList.add('acg-font-panel-open');
    renderPanel(overlay);
  };

  const closePanel = () => {
    const overlay = document.getElementById('acg-font-panel');
    if (!overlay) return;
    overlay.classList.remove('is-open');
    document.documentElement.classList.remove('acg-font-panel-open');
  };

  const renderPanel = (overlay) => {
    const current = getPreset(read());
    const grid = overlay.querySelector('[data-font-grid]');
    if (grid) {
      grid.innerHTML = '';
      PRESETS.forEach((p) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'acg-font-choice';
        btn.dataset.id = p.id;
        btn.setAttribute('aria-pressed', p.id === current.id ? 'true' : 'false');
        btn.innerHTML = `
          <div class="acg-font-choice__name">${p.name}</div>
          <div class="acg-font-choice__preview" style="font-family:${p.body}">示例文本 Aa 123，中文阅读更舒服</div>
        `;
        btn.addEventListener('click', () => {
          write(p.id);
          applyPreset(p);
          const floatBtn = document.getElementById('acg-font-switch');
          updateBtn(floatBtn, p);
          renderPanel(overlay);
        });
        grid.appendChild(btn);
      });
    }

    const waifu = overlay.querySelector('[data-waifu-toggle]');
    if (waifu) {
      waifu.checked = !readWaifu();
      waifu.onchange = () => {
        writeWaifu(!waifu.checked);
        // waifu-toggle.js will observe and apply; we also dispatch a storage event-like signal
        window.dispatchEvent(new Event('acgWaifuPrefChanged'));
      };
    }
  };

  const init = () => {
    const current = read();
    const preset = getPreset(current);
    applyPreset(preset);

    const btn = ensureBtn();
    if (!btn) return;
    if (!btn.__acgFontBound) {
      btn.__acgFontBound = true;
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        openPanel();
      });
    }
    updateBtn(btn, preset);
  };

  init();
  if (window.btf && typeof window.btf.addGlobalFn === 'function') {
    window.btf.addGlobalFn('pjaxComplete', init, 'acg_font_switch');
    window.btf.addGlobalFn('themeChange', init, 'acg_font_switch_theme');
  }
})();

