/* ---- 1. Card Motion Plus ---- */
(() => {
  'use strict';

  const CARD_SELECTOR = '#recent-posts .recent-post-item';
  const MAX_TILT = 6;

  function resetCard(card) {
    card.style.setProperty('--tilt-x', '0deg');
    card.style.setProperty('--tilt-y', '0deg');
    card.style.setProperty('--mx', '50%');
    card.style.setProperty('--my', '50%');
  }

  function bindCard(card) {
    if (card.dataset.motionBound === '1') return;
    card.dataset.motionBound = '1';

    resetCard(card);

    card.addEventListener('mousemove', (event) => {
      const rect = card.getBoundingClientRect();
      const px = (event.clientX - rect.left) / rect.width;
      const py = (event.clientY - rect.top) / rect.height;
      const tiltY = (px - 0.5) * (MAX_TILT * 2);
      const tiltX = (0.5 - py) * (MAX_TILT * 2);

      card.style.setProperty('--tilt-x', `${tiltX.toFixed(2)}deg`);
      card.style.setProperty('--tilt-y', `${tiltY.toFixed(2)}deg`);
      card.style.setProperty('--mx', `${(px * 100).toFixed(2)}%`);
      card.style.setProperty('--my', `${(py * 100).toFixed(2)}%`);
    });

    card.addEventListener('mouseleave', () => {
      resetCard(card);
    });

    card.addEventListener('mousedown', () => {
      card.classList.add('is-pressing');
    });

    window.addEventListener('mouseup', () => {
      card.classList.remove('is-pressing');
    });
  }

  function initCardMotion() {
    const cards = document.querySelectorAll(CARD_SELECTOR);
    cards.forEach(bindCard);
  }

  document.addEventListener('DOMContentLoaded', initCardMotion);
  document.addEventListener('pjax:complete', initCardMotion);
})();


/* ---- 2. Cursor Beauty ---- */
(function () {
  const isCoarsePointer = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
  if (isCoarsePointer) return;

  document.documentElement.classList.add('beauty-cursor-on');

  const dot = document.createElement('div');
  dot.className = 'beauty-cursor-dot';
  document.body.appendChild(dot);
  const ring = document.createElement('div');
  ring.className = 'beauty-cursor-ring';
  document.body.appendChild(ring);

  let mouseX = window.innerWidth / 2;
  let mouseY = window.innerHeight / 2;
  let ringX = mouseX;
  let ringY = mouseY;
  let hoverTarget = null;

  const move = (x, y) => {
    dot.style.setProperty('--cursor-x', `${x}px`);
    dot.style.setProperty('--cursor-y', `${y}px`);
  };
  const moveRing = (x, y) => {
    ring.style.setProperty('--cursor-x', `${x}px`);
    ring.style.setProperty('--cursor-y', `${y}px`);
  };

  const lerp = (a, b, n) => a + (b - a) * n;
  const hoverSelector = 'a, button, [role="button"], .menu-item, .aplayer button, .post-title, .article-title';
  const tick = () => {
    let targetX = mouseX;
    let targetY = mouseY;

    if (hoverTarget && hoverTarget.isConnected) {
      const rect = hoverTarget.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;
      const pullX = (centerX - mouseX) * 0.08;
      const pullY = (centerY - mouseY) * 0.08;
      const pullLen = Math.hypot(pullX, pullY);
      const maxPull = 5;
      const scale = pullLen > maxPull ? (maxPull / pullLen) : 1;
      targetX = mouseX + pullX * scale;
      targetY = mouseY + pullY * scale;
    }

    ringX = lerp(ringX, targetX, 0.42);
    ringY = lerp(ringY, targetY, 0.42);
    moveRing(ringX, ringY);
    window.requestAnimationFrame(tick);
  };

  document.addEventListener(
    'mousemove',
    (e) => {
      mouseX = e.clientX;
      mouseY = e.clientY;
      move(mouseX, mouseY);

      const t = e.target && e.target.closest ? e.target.closest(hoverSelector) : null;
      hoverTarget = t || null;
      ring.classList.toggle('is-hover', !!hoverTarget);
    },
    { passive: true }
  );

  document.addEventListener(
    'mousedown',
    () => {
      dot.classList.add('is-down');
      ring.classList.add('is-down');
    },
    { passive: true }
  );

  document.addEventListener(
    'mouseup',
    () => {
      dot.classList.remove('is-down');
      ring.classList.remove('is-down');
    },
    { passive: true }
  );

  document.addEventListener(
    'mouseleave',
    () => {
      dot.style.opacity = '0';
      ring.style.opacity = '0';
      hoverTarget = null;
      ring.classList.remove('is-hover');
    },
    { passive: true }
  );
  document.addEventListener(
    'mouseenter',
    () => {
      dot.style.opacity = '1';
      ring.style.opacity = '1';
    },
    { passive: true }
  );

  move(mouseX, mouseY);
  moveRing(ringX, ringY);
  window.requestAnimationFrame(tick);
})();

/* ---- 3. Navigation Active State ---- */
(() => {
  'use strict';

  function setActiveNav() {
    const path = window.location.pathname;
    const menuItems = document.querySelectorAll('#nav .menus_items .menus_item a.site-page');

    menuItems.forEach(item => {
      item.classList.remove('is-active');
      const href = item.getAttribute('href');
      if (href === '/' && path === '/') {
        item.classList.add('is-active');
      } else if (href !== '/' && path.startsWith(href)) {
        item.classList.add('is-active');
      }
    });
  }

  setActiveNav();
  if (window.btf && typeof window.btf.addGlobalFn === 'function') {
    window.btf.addGlobalFn('pjaxComplete', setActiveNav, 'nav_active');
  }
})();

