/* 字体声明已移至 inject.head 作为 preload，避免 @import 阻塞渲染 */

/* 首页标题和副标题样式 */
#site-title {
  font-size: 6rem;
  font-weight: 700;
  line-height: 1.2;
  color: #ffffff;
  text-align: center;
  margin-bottom: 20px;
}

#site-subtitle {
  font-size: 2.8rem;
  font-weight: 600;
  color: #ffffff;
  text-align: center;
}

/* 首页标题下方：保留标题，隐藏主题原副标题 */
#page-header.full_page #site-title {
  display: block !important;
  margin-bottom: 10px;
}

#page-header.full_page #site-subtitle {
  display: none !important;
}

/* 隐藏首页文章卡片的摘要内容 */
#recent-posts .recent-post-item .content {
  display: none !important;
}

/* 隐藏侧边栏标签云 */
.card-tags {
  display: none !important;
}

/* 隐藏首页文章卡片的标签 */
#recent-posts .recent-post-item .article-meta.tags {
  display: none !important;
}

/* JS 未执行时：仍显示整句（与 #home-hero-typewriter 二选一，避免重复） */
#page-header.full_page #site-info:not(:has(#home-hero-typewriter)) #site-title::after {
  content: '当你为错过太阳哭泣的时候，你也要错过群星了';
  display: block;
  margin: 14px auto 0;
  max-width: min(90vw, 980px);
  color: rgba(255, 255, 255, 0.97);
  font-size: 2rem;
  font-weight: 600;
  line-height: 1.45;
  text-align: center;
  text-shadow: 0 3px 14px rgba(0, 0, 0, 0.25);
}

/* 首页自定义打字机文案（JS 兜底保留） */
#home-hero-typewriter {
  display: block !important;
  opacity: 1 !important;
  visibility: visible !important;
  position: relative;
  left: auto;
  top: auto;
  transform: none;
  width: min(90vw, 980px);
  z-index: 3;
  pointer-events: none;
  margin: 14px auto 0;
  color: rgba(255, 255, 255, 0.97);
  text-align: center;
  font-size: 2rem;
  font-weight: 600;
  line-height: 1.45;
  text-shadow: 0 3px 14px rgba(0, 0, 0, 0.25);
}

/* Fallback: if JS timing fails and text is empty, still show sentence */
#home-hero-typewriter:empty::before {
  content: '当你为错过太阳哭泣的时候，你也要错过群星了';
}

#home-hero-typewriter::after {
  content: '|';
  margin-left: 4px;
  opacity: 1;
  animation: hero-typing-caret 1s steps(1) infinite;
}

#home-hero-typewriter.is-done::after {
  display: none;
}

@keyframes hero-typing-caret {
  50% {
    opacity: 0;
  }
}

