/* iOS-like switch */
.acg-switch {
  display: inline-flex;
  align-items: center;
}
.acg-switch input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.acg-switch__track {
  width: 46px;
  height: 26px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.55);
  border: 1px solid rgba(0, 0, 0, 0.08);
  position: relative;
  transition: background 0.18s ease, border-color 0.18s ease;
}
.acg-switch__track::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  transform: translateY(-50%);
  transition: left 0.18s ease;
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.18);
}
.acg-switch input:checked + .acg-switch__track {
  background: rgba(34, 197, 94, 0.75);
  border-color: rgba(34, 197, 94, 0.55);
}
.acg-switch input:checked + .acg-switch__track::after {
  left: 23px;
}

