/* ==========================================================================
   ★ 文章页顶栏：移除背景图，用柔和渐变 + 柔和分割线
   ==========================================================================
   Butterfly 模板在 <header style="background: url(...) center / cover no-repeat">
   内联 background shorthand 会同时设置 background-image / -size / -position / -repeat。
   必须逐个重置，且 body.post 在 Butterfly 默认 Pug 输出中不存在，
   所以用 .post-bg（模板 class）作为锚点 + !important 覆盖内联。

   注意：.full_page 是首页，不在此范围内。
   .post-bg 是文章页，.not-home-page 是标签/分类/归档页。
   只对 post-bg 起效，其他页面保留自己的 top_img。
   ========================================================================== */

/* 文章页顶栏：保留封面图作为背景 + 白色半透明波浪过渡 */
#page-header.post-bg {
  min-height: 380px !important;
  height: 440px !important;
  display: flex !important;
  align-items: center;
  justify-content: center;
  position: relative;
  /* 保留主题内联背景图，并确保居中裁剪显示人物 */
  background-size: cover !important;
  background-position: center 30% !important;
  padding-top: 60px !important;
}
/* 不重置背景图，让主题内联的封面图继续显示 */

/* 导航栏：封面图上半透明玻璃效果，白字 */
#page-header.post-bg #nav {
  z-index: 5;
  background: rgba(0, 0, 0, 0.18) !important;
  backdrop-filter: saturate(150%) blur(10px);
  -webkit-backdrop-filter: saturate(150%) blur(10px);
}

#page-header.post-bg #nav a,
#page-header.post-bg #nav span.site-page,
#page-header.post-bg #nav i {
  color: rgba(255, 255, 255, 0.95) !important;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.35) !important;
}

/* 文章标题：居中，白色大字，带阴影，叠在封面上 */
#page-header.post-bg #post-info {
  position: relative;
  z-index: 3;
  text-align: center;
  padding: 20px 20px 60px;
}

#page-header.post-bg #post-info .post-title {
  font-size: clamp(2.2rem, 5vw, 3.2rem) !important;
  font-weight: 900 !important;
  color: #fff !important;
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.45), 0 0 60px rgba(255, 255, 255, 0.15);
  letter-spacing: 0.06em;
  margin: 0 !important;
