/* 信封卡片内：分类/标签 → 紧凑小胶囊 */
#recent-posts .recent-post-item:has(> .post_cover) .article-meta__categories,
#recent-posts .recent-post-item:has(> .post_cover) .article-meta__tags {
  display: inline-flex !important;
