}

/* 首页封面图上：文字变白 + 阴影（提高对比度）
   注意：不要把图标强制变白，这样彩色图标才“精美” */
#page-header.full_page #nav a,
#page-header.full_page #nav span.site-page,
#page-header.full_page #nav .site-name,
#page-header.full_page #nav i {
