  border-color: rgba(192, 132, 252, 0.4);
}

[data-theme='dark'] #page .tag-cloud-list a {
  border-color: rgba(255, 255, 255, 0.32) !important;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.55);
}

