}

#article-container .about-chip {
  display: inline-flex;
  align-items: center;
  padding: 0.32em 0.75em;
  font-size: 0.82rem;
  font-weight: 700;
  border-radius: 999px;
  border: 1px solid rgba(244, 114, 182, 0.35);
  background: linear-gradient(165deg, rgba(253, 242, 248, 0.95), rgba(240, 249, 255, 0.9));
