/* Font settings panel (modal) */
.acg-font-panel {
  position: fixed;
  inset: 0;
  z-index: 100200;
  display: none;
}
.acg-font-panel.is-open {
  display: block;
}
.acg-font-panel__mask {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.acg-font-panel__card {
  position: absolute;
  right: 16px;
  bottom: 96px;
  z-index: 1;
  width: min(420px, calc(100vw - 32px));
  border-radius: 16px;
  padding: 14px 14px 12px;
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.55);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.18);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  transform: translateY(6px);
  animation: acgFontPanelIn 0.18s ease-out forwards;
}
@keyframes acgFontPanelIn {
  to { transform: translateY(0); }
}

[data-theme="dark"] .acg-font-panel__card {
  background: rgba(18, 18, 24, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.55);
}

.acg-font-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 2px 2px 10px;
}
.acg-font-panel__title {
  font-weight: 900;
  letter-spacing: 0.2px;
}
.acg-font-panel__close {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  border: 1px solid rgba(0, 0, 0, 0.08);
  background: rgba(255, 255, 255, 0.65);
  color: inherit;
}
[data-theme="dark"] .acg-font-panel__close {
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
}
.acg-font-panel__close:hover {
  transform: translateY(-1px);
}

.acg-font-panel__section {
