  gap: 10px;
}
@media (max-width: 420px) {
  .acg-font-panel__grid { grid-template-columns: 1fr; }
  .acg-font-panel__card { right: 12px; bottom: 88px; }
}

.acg-font-choice {
  text-align: left;
  border-radius: 14px;
  padding: 10px 12px;
  border: 1px solid rgba(0, 0, 0, 0.08);
  background: rgba(255, 255, 255, 0.64);
  color: inherit;
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.08);
  transition: transform 0.16s ease, box-shadow 0.16s ease, border-color 0.16s ease;
}
[data-theme="dark"] .acg-font-choice {
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.35);
}
.acg-font-choice:hover {
  transform: translateY(-1px);
  box-shadow: 0 14px 26px rgba(0, 0, 0, 0.12);
}
.acg-font-choice[aria-pressed="true"] {
  border-color: rgba(96, 165, 250, 0.55);
  box-shadow: 0 14px 30px rgba(96, 165, 250, 0.18);
}

.acg-font-choice__name {
  font-weight: 900;
  margin-bottom: 6px;
}
.acg-font-choice__preview {
