  max-width: min(240px, 44vw);
}

.page.type-categories #page .acg-chip:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--chip-color, #38bdf8) 26%, rgba(255,255,255,0.78));
