  --custom-font-body: "LXGW WenKai Screen", "PingFang SC", "Microsoft YaHei", "Noto Sans SC", system-ui, sans-serif;
  --custom-font-heading: "Poppins", "Inter", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  --custom-font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Courier New", monospace;
  /* Global switchable fonts (overridden by JS) */
  --site-font-body: var(--custom-font-body);
  --site-font-heading: var(--custom-font-heading);
}

body {
  font-family: var(--site-font-body) !important;
  font-size: 16px;
  line-height: 1.75;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  letter-spacing: -0.01em;
}

#page,
#nav,
#recent-posts,
#article-container,
#post,
#aside-content {
  font-family: var(--site-font-body) !important;
}

/* 正文段落更“顺”：行高 + 上下间距 */
#post .post-content p,
#article-container .post-content p {
  line-height: 1.95;
  margin: 0.95em 0;
}

/* 标题更利落：不改字号，只优化节奏 */
#post .post-content h1,
#post .post-content h2,
#post .post-content h3 {
  line-height: 1.22;
  letter-spacing: -0.02em;
}

/* 保护代码块：仍使用等宽字体，避免被全站 sans 影响 */
pre,
code,
kbd,
samp {
  font-family: var(--custom-font-mono);
}

/* ------------------------------
   Article typography: focus on readability
   Only affects article/page main content
   ------------------------------ */
#post .post-content,
#article-container .post-content {
  font-family: var(--site-font-body) !important;
  font-size: 1.04rem;
  line-height: 1.9;
  color: rgba(15, 23, 42, 0.86);
  font-weight: 450;
  letter-spacing: -0.01em;
  text-wrap: pretty;
}

[data-theme='dark'] #post .post-content,
[data-theme='dark'] #article-container .post-content {
  color: rgba(226, 232, 240, 0.88);
}

/* Headings: clearer hierarchy + spacing */
#post .post-content h1,
#post .post-content h2,
#post .post-content h3,
#post .post-content h4,
#article-container .post-content h1,
#article-container .post-content h2,
#article-container .post-content h3,
#article-container .post-content h4 {
  font-family: var(--site-font-heading) !important;
  margin: 1.35em 0 0.6em;
  font-weight: 850;
  color: rgba(15, 23, 42, 0.92);
}

/* Font switch button (rightside) */
#rightside-config-show #acg-font-switch.acg-font-switch {
  background: linear-gradient(135deg, #60a5fa, #a78bfa) !important;
  color: #fff !important;
  box-shadow: 0 12px 28px rgba(96, 165, 250, 0.25) !important;
}

#rightside-config-show #acg-font-switch.acg-font-switch:hover {
  transform: translateY(-1px);
  box-shadow: 0 16px 36px rgba(167, 139, 250, 0.32) !important;
}

#acg-font-switch .acg-font-switch__a {
  font-weight: 900;
  font-size: 16px;
  line-height: 1;
  display: inline-block;
}

[data-theme='dark'] #post .post-content h1,
[data-theme='dark'] #post .post-content h2,
[data-theme='dark'] #post .post-content h3,
[data-theme='dark'] #post .post-content h4,
[data-theme='dark'] #article-container .post-content h1,
[data-theme='dark'] #article-container .post-content h2,
[data-theme='dark'] #article-container .post-content h3,
[data-theme='dark'] #article-container .post-content h4 {
  color: rgba(241, 245, 249, 0.94);
}

/* Paragraphs and lists */
#post .post-content p,
#article-container .post-content p {
  margin: 0.9em 0;
}

#post .post-content ul,
#post .post-content ol,
#article-container .post-content ul,
#article-container .post-content ol {
  margin: 0.85em 0;
  padding-left: 1.25em;
}

#post .post-content li,
#article-container .post-content li {
  margin: 0.35em 0;
}

/* Links: subtle but premium underline */
#post .post-content a,
#article-container .post-content a {
  color: #2563eb;
  text-decoration: none;
  border-bottom: 1px solid rgba(37, 99, 235, 0.28);
  transition: border-color 0.16s ease, color 0.16s ease, background-color 0.16s ease;
}

#post .post-content a:hover,
#article-container .post-content a:hover {
  color: #1d4ed8;
  border-bottom-color: rgba(37, 99, 235, 0.62);
  background: rgba(37, 99, 235, 0.06);
}

[data-theme='dark'] #post .post-content a,
[data-theme='dark'] #article-container .post-content a {
  color: #7dd3fc;
  border-bottom-color: rgba(125, 211, 252, 0.28);
}

[data-theme='dark'] #post .post-content a:hover,
[data-theme='dark'] #article-container .post-content a:hover {
  border-bottom-color: rgba(125, 211, 252, 0.62);
  background: rgba(56, 189, 248, 0.10);
}

/* Blockquote: cleaner */
#post .post-content blockquote,
#article-container .post-content blockquote {
  margin: 1.0em 0;
  padding: 0.9em 1.0em;
  border-left: 4px solid rgba(56, 189, 248, 0.65);
  background: rgba(241, 245, 249, 0.65);
  border-radius: 12px;
  color: rgba(51, 65, 85, 0.84);
}

[data-theme='dark'] #post .post-content blockquote,
[data-theme='dark'] #article-container .post-content blockquote {
  background: rgba(30, 41, 59, 0.55);
  color: rgba(226, 232, 240, 0.86);
  border-left-color: rgba(94, 234, 212, 0.55);
}

/* Inline code: a bit softer than code blocks */
#post .post-content :not(pre) > code,
#article-container .post-content :not(pre) > code {
  font-size: 0.95em;
  padding: 0.16em 0.42em;
  border-radius: 8px;
  background: rgba(226, 232, 240, 0.65);
  border: 1px solid rgba(148, 163, 184, 0.22);
}

[data-theme='dark'] #post .post-content :not(pre) > code,
[data-theme='dark'] #article-container .post-content :not(pre) > code {
  background: rgba(15, 23, 42, 0.55);
  border-color: rgba(148, 163, 184, 0.16);
}

/* ------------------------------
   Tags page only: compact glass panel + gentle heat bars
   ------------------------------ */
.page.type-tags .layout > #page {
  padding: 28px 26px 22px !important;
}

.page.type-tags #page .tag-cloud-list {
  position: relative;
  max-width: 980px;
  margin: 0 auto !important;
  padding: 18px 20px 20px !important;
  text-align: center !important;
  border: 1px solid rgba(255, 255, 255, 0.44);
  border-radius: 20px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.72), rgba(255, 255, 255, 0.58)),
    radial-gradient(circle at 18% 14%, rgba(56, 189, 248, 0.14), transparent 34%),
    radial-gradient(circle at 84% 82%, rgba(244, 114, 182, 0.14), transparent 34%);
  box-shadow: 0 14px 38px rgba(15, 23, 42, 0.10);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

.page.type-tags #page .tag-cloud-list::after {
  content: '';
  display: block;
  width: min(400px, 60%);
  height: 1px;
  margin: 16px auto 4px;
  background: linear-gradient(90deg, transparent, rgba(148, 163, 184, 0.4), transparent);
}

.page.type-tags #page .tag-cloud-list a {
  display: inline-block;
  margin: 3px 5px !important;
  padding: 0.32em 0.9em !important;
  border: 1px solid rgba(255, 255, 255, 0.58) !important;
  border-radius: 999px !important;
  background-image: linear-gradient(135deg, rgba(255, 255, 255, 0.34), rgba(255, 255, 255, 0.04)) !important;
  background-blend-mode: overlay !important;
  box-shadow:
    0 7px 16px rgba(15, 23, 42, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.28) !important;
  line-height: 1.35 !important;
  text-shadow: 0 1px 2px rgba(15, 23, 42, 0.34);
  transition: transform 0.18s ease, filter 0.18s ease, box-shadow 0.18s ease !important;
}

.page.type-tags #page .tag-cloud-list a:hover {
  transform: translateY(-2px) scale(1.03) !important;
  filter: brightness(1.06);
  box-shadow:
    0 12px 28px rgba(15, 23, 42, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.36) !important;
}

[data-theme='dark'] .page.type-tags #page .tag-cloud-list a {
  border-color: rgba(255, 255, 255, 0.34) !important;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.55);
  box-shadow:
    0 8px 18px rgba(0, 0, 0, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.18) !important;
}

[data-theme='dark'] .page.type-tags #page .tag-cloud-list {
  border-color: rgba(148, 163, 184, 0.24);
  background:
    linear-gradient(180deg, rgba(30, 41, 59, 0.62), rgba(15, 23, 42, 0.56)),
    radial-gradient(circle at 18% 14%, rgba(56, 189, 248, 0.18), transparent 36%),
    radial-gradient(circle at 84% 82%, rgba(244, 114, 182, 0.18), transparent 36%);
  box-shadow: 0 16px 42px rgba(0, 0, 0, 0.34);
}

.page.type-tags #page .tag-cloud-heat {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: flex-end;
  gap: 8px;
  max-width: 680px;
  margin: 10px auto 0;
  padding: 18px 14px 12px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.46);
  background:
    radial-gradient(circle at 50% 0%, rgba(56, 189, 248, 0.12), transparent 48%),
    radial-gradient(circle at 10% 95%, rgba(244, 114, 182, 0.12), transparent 50%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.70), rgba(255, 255, 255, 0.56));
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.10);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

.page.type-tags #page .tag-cloud-heat::before {
  content: '热度分布';
  position: absolute;
  left: 50%;
  top: 10px;
  transform: translateX(-50%);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.28em;
  text-indent: 0.28em;
  text-transform: uppercase;
  opacity: 0.70;
  color: rgba(15, 23, 42, 0.70);
  pointer-events: none;
}

.page.type-tags #page .tag-cloud-heat::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background:
    radial-gradient(circle, rgba(15, 23, 42, 0.06) 0 1px, transparent 1.2px) 0 0 / 14px 14px;
  opacity: 0.55;
  pointer-events: none;
  mask-image: radial-gradient(circle at 50% 40%, #000 0 56%, transparent 72%);
}

[data-theme='dark'] .page.type-tags #page .tag-cloud-heat {
  border-color: rgba(148, 163, 184, 0.22);
  background:
    radial-gradient(circle at 50% 0%, rgba(56, 189, 248, 0.16), transparent 52%),
    radial-gradient(circle at 10% 95%, rgba(244, 114, 182, 0.16), transparent 55%),
    linear-gradient(180deg, rgba(30, 41, 59, 0.62), rgba(15, 23, 42, 0.56));
  box-shadow: 0 16px 42px rgba(0, 0, 0, 0.34);
}

[data-theme='dark'] .page.type-tags #page .tag-cloud-heat::before {
  color: rgba(226, 232, 240, 0.82);
}

.page.type-tags #page .tag-cloud-heat__bar {
  position: relative;
  display: block;
  width: clamp(34px, 5.4vw, 52px);
  height: 72px;
  border-radius: 8px 8px 4px 4px;
  background: linear-gradient(180deg, hsl(var(--bar-hue) 88% 70% / .95), hsl(var(--bar-hue) 88% 50% / .95));
  box-shadow: 0 8px 16px rgba(15, 23, 42, 0.14);
  transform-origin: bottom;
  /* --bar-height is a percentage string like "67%" */
  transform: scaleY(calc(var(--bar-height) / 100%));
  transition: transform 0.18s ease, filter 0.18s ease;
}

.page.type-tags #page .tag-cloud-heat__bar:hover {
  filter: brightness(1.08);
  transform: scaleY(calc(var(--bar-height) / 100%)) translateY(-2px);
}

.page.type-tags #page .tag-cloud-heat__bar::before {
  content: none;
}

.page.type-tags #page .tag-cloud-heat__bar:hover::before {
  content: none;
}

/* Tooltip (JS enhanced) */
.acg-tags-heat-tooltip {
  position: fixed;
  left: 0;
  top: 0;
  z-index: 100500;
  transform: translate3d(-9999px, -9999px, 0);
  opacity: 0;
  pointer-events: none;
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.52);
  background: rgba(15, 23, 42, 0.86);
  color: rgba(255, 255, 255, 0.92);
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.26);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  font-size: 12px;
  line-height: 1.2;
  transition: opacity 0.12s ease, transform 0.08s linear;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.acg-tags-heat-tooltip::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -6px;
  width: 10px;
  height: 10px;
  background: inherit;
  border-left: 1px solid rgba(255, 255, 255, 0.26);
  border-bottom: 1px solid rgba(255, 255, 255, 0.26);
  transform: translateX(-50%) rotate(-45deg);
}

.acg-tags-heat-tooltip.is-show {
  opacity: 1;
}

.acg-tags-heat-tooltip__label {
  font-weight: 900;
  letter-spacing: 0.2px;
}

.acg-tags-heat-tooltip__count {
  opacity: 0.88;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

[data-theme='dark'] .acg-tags-heat-tooltip {
  border-color: rgba(148, 163, 184, 0.22);
  background: rgba(2, 6, 23, 0.84);
  box-shadow: 0 16px 44px rgba(0, 0, 0, 0.42);
}

@media (max-width: 768px) {
  .page.type-tags .layout > #page {
    padding: 16px 10px 14px !important;
  }

  .page.type-tags #page .tag-cloud-list {
    padding: 12px 10px 14px !important;
    border-radius: 14px;
  }

  .page.type-tags #page .tag-cloud-heat {
    gap: 6px;
    margin-top: 10px;
  }

  .page.type-tags #page .tag-cloud-heat__bar {
    width: clamp(26px, 7.4vw, 38px);
    height: 58px;
  }
}

/* ==========================================================================
   ★ Top Reading Progress Bar (thin gradient at the very top of viewport)
   ========================================================================== */
.reading-progress-bar {
  position: fixed;
  top: 0;
  left: 0;
  width: 0%;
  height: 3px;
  z-index: 200000;
  background: linear-gradient(90deg, #38bdf8, #818cf8, #f472b6, #fb7185);
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.55);
  transition: width 0.15s ease-out;
  pointer-events: none;
}

/* ==========================================================================
   ★ Custom Scrollbar (subtle, matching theme color)
   ========================================================================== */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: rgba(241, 245, 249, 0.6);
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, rgba(56, 189, 248, 0.45), rgba(129, 140, 248, 0.45));
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}

::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, rgba(56, 189, 248, 0.7), rgba(129, 140, 248, 0.7));
  background-clip: padding-box;
}

[data-theme='dark'] ::-webkit-scrollbar-track {
  background: rgba(15, 23, 42, 0.4);
}

[data-theme='dark'] ::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, rgba(56, 189, 248, 0.35), rgba(129, 140, 248, 0.35));
}

[data-theme='dark'] ::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, rgba(56, 189, 248, 0.6), rgba(129, 140, 248, 0.6));
}

/* Firefox */
* {
  scrollbar-width: thin;
  scrollbar-color: rgba(56, 189, 248, 0.45) rgba(241, 245, 249, 0.6);
}

[data-theme='dark'] * {
  scrollbar-color: rgba(56, 189, 248, 0.35) rgba(15, 23, 42, 0.4);
}

/* ==========================================================================
   ★ Article Image: Subtle Hover Zoom Effect
   ========================================================================== */
#article-container .post-content img,
#post .post-content img {
  transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
              box-shadow 0.35s cubic-bezier(0.22, 1, 0.36, 1);
  cursor: zoom-in;
}

#article-container .post-content img:hover,
#post .post-content img:hover {
  transform: scale(1.02);
  box-shadow:
    0 8px 30px rgba(15, 23, 42, 0.15),
    0 2px 10px rgba(15, 23, 42, 0.1);
}

[data-theme='dark'] #article-container .post-content img:hover,
[data-theme='dark'] #post .post-content img:hover {
  box-shadow:
    0 10px 36px rgba(0, 0, 0, 0.45),
    0 2px 12px rgba(0, 0, 0, 0.3);
}

/* ==========================================================================
   ★ Text Selection: Animated Highlight
   ========================================================================== */
::selection {
  background: rgba(56, 189, 248, 0.25);
  color: inherit;
}

[data-theme='dark'] ::selection {
  background: rgba(94, 234, 212, 0.25);
}

/* ==========================================================================
   ★ Footer: Wave Decoration + Better Spacing
   ========================================================================== */
#footer {
  position: relative;
  overflow: hidden;
}

#footer::before {
  display: none !important;
}

#footer #footer-wrap {
  padding-top: 1.2rem;
}

#footer .footer-copyright {
  display: block !important;
}

#footer .footer-copyright .framework-info {
  display: none !important;
}

#footer .footer-copyright a {
  color: rgba(255, 255, 255, 0.7);
  transition: color 0.2s ease;
}

#footer .footer-copyright a:hover {
  color: rgba(56, 189, 248, 0.9);
}

/* ==========================================================================
   ★ Archives Page: Timeline Style
   ========================================================================== */
.page.type-archives .article-container {
  position: relative;
  padding-left: 28px;
}

.page.type-archives .article-container::before {
  content: '';
  position: absolute;
  left: 8px;
  top: 0;
  bottom: 0;
  width: 2px;
  background: linear-gradient(180deg, rgba(56, 189, 248, 0.3), rgba(129, 140, 248, 0.3), rgba(244, 114, 182, 0.3));
  border-radius: 999px;
}

/* ==========================================================================
   ★ Post Content: Better Heading Hierarchy with Left Accent
   ========================================================================== */
#post .post-content h2,
#article-container .post-content h2 {
  position: relative;
  padding-left: 14px;
}

#post .post-content h2::before,
#article-container .post-content h2::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.15em;
  bottom: 0.15em;
  width: 4px;
  border-radius: 999px;
  background: linear-gradient(180deg, #38bdf8, #818cf8, #f472b6);
  transition: width 0.3s ease;
}

#post .post-content h2:hover::before,
#article-container .post-content h2:hover::before {
  width: 7px;
}

[data-theme='dark'] #post .post-content h2::before,
[data-theme='dark'] #article-container .post-content h2::before {
  background: linear-gradient(180deg, #5eead4, #818cf8, #f9a8d4);
}

/* ==========================================================================
   ★ Heading Icons: Different icons for h3 / h4 / h5
   ========================================================================== */
/* h3: ▸ 三角箭头，青绿色 */
#post .post-content h3,
#article-container .post-content h3 {
  position: relative;
  padding-left: 22px;
}

#post .post-content h3::before,
#article-container .post-content h3::before {
  content: '▸';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.85em;
  font-weight: 700;
  color: #14b8a6;
  line-height: 1;
  text-shadow: 0 0 6px rgba(20, 184, 166, 0.3);
}

[data-theme='dark'] #post .post-content h3::before,
[data-theme='dark'] #article-container .post-content h3::before {
  color: #5eead4;
  text-shadow: 0 0 8px rgba(94, 234, 212, 0.35);
}

/* h4: ◆ 实心菱形，珊瑚粉 */
#post .post-content h4,
#article-container .post-content h4 {
  position: relative;
  padding-left: 20px;
}

#post .post-content h4::before,
#article-container .post-content h4::before {
  content: '◆';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.55em;
  font-weight: 900;
  color: #f472b6;
  line-height: 1;
  text-shadow: 0 0 6px rgba(244, 114, 182, 0.3);
}

[data-theme='dark'] #post .post-content h4::before,
[data-theme='dark'] #article-container .post-content h4::before {
  color: #f9a8d4;
  text-shadow: 0 0 8px rgba(249, 168, 212, 0.35);
}

/* h5: ● 实心圆点，天蓝色 */
#post .post-content h5,
#article-container .post-content h5 {
  position: relative;
  padding-left: 18px;
}

#post .post-content h5::before,
#article-container .post-content h5::before {
  content: '●';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.48em;
  font-weight: 900;
  color: #38bdf8;
  line-height: 1;
  text-shadow: 0 0 5px rgba(56, 189, 248, 0.3);
}

[data-theme='dark'] #post .post-content h5::before,
[data-theme='dark'] #article-container .post-content h5::before {
  color: #7dd3fc;
  text-shadow: 0 0 6px rgba(125, 211, 252, 0.35);
}


/* ==========================================================================
   ★ Page Header Banners: for tags, categories, archives (NOT posts)
   ========================================================================== */
/* 标签/分类/归档页顶部横幅 */
#page-header:not(.full_page):not(.post-bg) {
  position: relative !important;
  min-height: 280px !important;
  height: auto !important;
  max-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: visible;
}

/* 不加额外的渐变遮罩 — 保留原始背景图可见 */

/* ===== 前层白色波浪：12秒来回漂移（更平缓曲线） ===== */
#page-header:not(.full_page):not(.post-bg)::after {
  content: '';
  position: absolute;
